// The floor's boundaries, refused by a machine instead of asserted in a sentence (runward ADR-0115).
//
// The mission says the core is a pure domain behind four ports (architecture.md §2, ADR-0001), that
// nothing the model proposes is ever executed (ADR-0002, threat-model.md §3), and that no credential
// lives in the code (config-secrets-boundary). Each of those sentences is a lint rule below, so a
// change that breaks one is an error in reports/eslint.json and reports/eslint.sarif, the two
// reports the manifests cite, regenerated by `npm run reports` and compared in CI by
// `npm run reports:fresh`.
//
// What a lint rule can and cannot say, plainly: it refuses the SHAPES it names (an import, a call, a
// literal). It does not prove the code is correct, and a credential spelled in a shape not listed
// here is not seen. A project that holds real secrets runs a secret scanner as well and commits its
// SARIF; this example holds none and keeps one dependency set: ESLint and its TypeScript parser.
import tsParser from "@typescript-eslint/parser";

// The literal shapes of common credentials: a model or SaaS API key, a cloud access key id, a
// forge token, a chat token, a private key block, a password inside a connection URL, a bearer
// token. Matched on string literals and on the text of template literals.
const CREDENTIAL = [
  "sk-[A-Za-z0-9_-]{16,}",
  "AKIA[0-9A-Z]{16}",
  "(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{30,}",
  "github_pat_[A-Za-z0-9_]{30,}",
  "xox[abposr]-[A-Za-z0-9-]{10,}",
  "-----BEGIN [A-Z ]*PRIVATE KEY-----",
  "[a-z][a-z0-9+.-]*:\\/\\/[^\\s:@\\/]+:[^\\s@\\/]+@",
  "[Bb]earer [A-Za-z0-9._~+-]{20,}",
].join("|");
const NO_CREDENTIAL = [
  { selector: `Literal[value=/${CREDENTIAL}/]`, message: "a credential in the code: read it from typed configuration at the boundary, never from a literal (config-secrets-boundary)" },
  { selector: `TemplateElement[value.raw=/${CREDENTIAL}/]`, message: "a credential in the code: read it from typed configuration at the boundary, never from a literal (config-secrets-boundary)" },
];
// The core loads nothing at run time: a dynamic import or a require is a way around the import
// boundary below (no-restricted-imports reads static imports only).
const NO_RUNTIME_LOADING = [
  { selector: "ImportExpression", message: "the core loads no module at run time: a dynamic import goes around the hexagonal boundary" },
  { selector: "CallExpression[callee.name='require']", message: "the core loads no module at run time: require goes around the hexagonal boundary" },
];

export default [
  {
    files: ["src/**/*.ts"],
    // The timer globals are declared so that no-implied-eval sees `setTimeout("code")` for what it is.
    languageOptions: { parser: tsParser, ecmaVersion: 2022, sourceType: "module", globals: { setTimeout: "readonly", setInterval: "readonly", setImmediate: "readonly" } },
    // A finding is fixed in the code or decided in this file, never silenced beside it: an
    // `eslint-disable` comment has no effect here (ESLint says so, as a warning, where it sits).
    linterOptions: { noInlineConfig: true },
    rules: {
      // Nothing the model proposes, and nothing a request carries, is ever run as code (ADR-0002).
      "no-eval": "error",
      "no-implied-eval": "error",
      "no-new-func": "error",
      "no-restricted-syntax": ["error", ...NO_CREDENTIAL],
    },
  },
  {
    // The hexagon (architecture.md §2): the core imports its own modules and its validation
    // library, nothing else. No database driver, no HTTP client, no model SDK, no Node.js built-in
    // (no `child_process`, no `fs`), and never an adapter.
    files: ["src/core/**/*.ts"],
    rules: {
      "no-restricted-imports": ["error", {
        patterns: [
          { regex: "^(?!\\.{1,2}/)(?!zod$)", message: "the core imports no infrastructure: only its own modules and zod (hexagonal boundary, architecture.md §2)" },
          { regex: "(^|/)adapters(/|$)", message: "the core never imports an adapter: adapters implement the core's ports (hexa-adapter-pattern)" },
        ],
      }],
      // The network is an adapter's concern; the core calls none.
      "no-restricted-globals": ["error",
        { name: "fetch", message: "the core makes no network call: put it behind a port, in an adapter" },
        { name: "XMLHttpRequest", message: "the core makes no network call: put it behind a port, in an adapter" },
        { name: "WebSocket", message: "the core makes no network call: put it behind a port, in an adapter" },
        { name: "EventSource", message: "the core makes no network call: put it behind a port, in an adapter" },
      ],
      // Flat config replaces a rule's options per file, it does not merge them: the core keeps the
      // credential selectors and adds its own.
      "no-restricted-syntax": ["error", ...NO_CREDENTIAL, ...NO_RUNTIME_LOADING],
    },
  },
];
